package syntax

func init() {
	doc("Date.add", "Adds a number of days, which may be negative.", "alx> Date.add(~D[2026-02-27], 2)", "~D[2026-03-01]")
	doc("Date.after?", "Reports whether the first date is later than the second.", "alx> Date.after?(~D[2026-03-01], ~D[2026-02-01])", "true")
	doc("Date.before?", "Reports whether the first date is earlier than the second.", "alx> Date.before?(~D[2026-03-01], ~D[2026-02-01])", "false")
	doc("Date.beginning_of_month", "The first day of the date's month.", "alx> Date.beginning_of_month(~D[2026-03-18])", "~D[2026-03-01]")
	doc("Date.beginning_of_week", "The Monday on or before the date.", "alx> Date.beginning_of_week(~D[2026-03-18])", "~D[2026-03-16]")
	doc("Date.compare", "Returns :lt, :eq or :gt as the first date is earlier than, equal to or later than the second.", "alx> Date.compare(~D[2026-01-01], ~D[2026-01-02])", ":lt")
	doc("Date.day_of_week", "The day of the week, from 1 for Monday to 7 for Sunday.", "alx> Date.day_of_week(~D[2026-03-18])", "3")
	doc("Date.day_of_year", "The day of the year, from 1.", "alx> Date.day_of_year(~D[2026-02-01])", "32")
	doc("Date.days_in_month", "The number of days in the date's month.", "alx> Date.days_in_month(~D[2024-02-10])", "29")
	doc("Date.diff", "The number of days from the second date to the first.", "alx> Date.diff(~D[2026-03-01], ~D[2026-02-01])", "28")
	doc("Date.end_of_month", "The last day of the date's month.", "alx> Date.end_of_month(~D[2026-02-10])", "~D[2026-02-28]")
	doc("Date.end_of_week", "The Sunday on or after the date.", "alx> Date.end_of_week(~D[2026-03-18])", "~D[2026-03-22]")
	doc("Date.from_iso8601", "Parses YYYY-MM-DD text, returning ok(date) or error(reason).", "alx> Date.from_iso8601(\"2026-03-18\")", "ok(~D[2026-03-18])")
	doc("Date.from_iso8601!", "Parses YYYY-MM-DD text; fails when it is invalid.", "alx> Date.from_iso8601!(\"2026-03-18\")", "~D[2026-03-18]")
	doc("Date.leap_year?", "Reports whether the date falls in a leap year.", "alx> Date.leap_year?(~D[2024-01-01])", "true")
	doc("Date.new", "Builds a date from year, month and day, returning an error for a date that does not exist.", "alx> Date.new(2026, 3, 18)", "ok(~D[2026-03-18])",
		"alx> case Date.new(2026, 2, 30) do", "...>   ok(_) -> \"valid\"", "...>   error(_) -> \"invalid\"", "...> end", "\"invalid\"")
	doc("Date.new!", "Builds a date from year, month and day; fails for a date that does not exist.", "alx> Date.new!(2026, 3, 18)", "~D[2026-03-18]")
	doc("Date.quarter_of_year", "The quarter, from 1 to 4.", "alx> Date.quarter_of_year(~D[2026-05-01])", "2")
	doc("Date.to_iso8601", "The date as YYYY-MM-DD text.", "alx> Date.to_iso8601(~D[2026-03-18])", "\"2026-03-18\"")
	doc("Date.to_string", "The date as YYYY-MM-DD text.", "alx> Date.to_string(~D[2026-03-18])", "\"2026-03-18\"")
	doc("Date.utc_today", "Today's date in UTC.", "alx> Date.after?(Date.utc_today(), ~D[2020-01-01])", "true")

	doc("Time.add", "Adds a number of seconds, wrapping around midnight.", "alx> Time.add(~T[23:59:30], 45)", "~T[00:00:15]")
	doc("Time.after?", "Reports whether the first time is later than the second.", "alx> Time.after?(~T[10:00:00], ~T[09:00:00])", "true")
	doc("Time.before?", "Reports whether the first time is earlier than the second.", "alx> Time.before?(~T[10:00:00], ~T[09:00:00])", "false")
	doc("Time.compare", "Returns :lt, :eq or :gt as the first time is earlier than, equal to or later than the second.", "alx> Time.compare(~T[10:00:00], ~T[10:00:00])", ":eq")
	doc("Time.diff", "The number of seconds from the second time to the first.", "alx> Time.diff(~T[10:01:00], ~T[10:00:00])", "60")
	doc("Time.from_iso8601", "Parses HH:MM:SS text, returning ok(time) or error(reason).", "alx> Time.from_iso8601(\"13:04:05\")", "ok(~T[13:04:05])")
	doc("Time.from_iso8601!", "Parses HH:MM:SS text; fails when it is invalid.", "alx> Time.from_iso8601!(\"13:04:05\")", "~T[13:04:05]")
	doc("Time.monotonic", "Milliseconds from a clock that never goes backwards, for measuring durations.", "alx> started = Time.monotonic()", "alx> Time.monotonic() >= started", "true")
	doc("Time.new", "Builds a time from hour, minute, second and optionally microsecond, returning an error when out of range.", "alx> Time.new(13, 4, 5)", "ok(~T[13:04:05])")
	doc("Time.new!", "Builds a time from hour, minute and second; fails when out of range.", "alx> Time.new!(13, 4, 5)", "~T[13:04:05]")
	doc("Time.now", "Milliseconds since the Unix epoch.", "alx> Time.now() > 1600000000000", "true")
	doc("Time.to_iso8601", "The time as HH:MM:SS text.", "alx> Time.to_iso8601(~T[13:04:05])", "\"13:04:05\"")
	doc("Time.to_string", "The time as HH:MM:SS text.", "alx> Time.to_string(~T[13:04:05])", "\"13:04:05\"")
	doc("Time.utc_now", "The current time of day in UTC.", "alx> now = Time.utc_now()", "alx> Time.compare(now, now)", ":eq")

	doc("NaiveDateTime.add", "Adds a number of seconds.", "alx> NaiveDateTime.add(~N[2026-01-05 23:59:59], 2)", "~N[2026-01-06 00:00:01]")
	doc("NaiveDateTime.after?", "Reports whether the first is later than the second.", "alx> NaiveDateTime.after?(~N[2026-01-06 00:00:00], ~N[2026-01-05 00:00:00])", "true")
	doc("NaiveDateTime.before?", "Reports whether the first is earlier than the second.", "alx> NaiveDateTime.before?(~N[2026-01-06 00:00:00], ~N[2026-01-05 00:00:00])", "false")
	doc("NaiveDateTime.compare", "Returns :lt, :eq or :gt as the first is earlier than, equal to or later than the second.", "alx> NaiveDateTime.compare(~N[2026-01-05 00:00:00], ~N[2026-01-06 00:00:00])", ":lt")
	doc("NaiveDateTime.diff", "The number of seconds from the second to the first.", "alx> NaiveDateTime.diff(~N[2026-01-06 00:00:00], ~N[2026-01-05 00:00:00])", "86400")
	doc("NaiveDateTime.from_iso8601", "Parses date and time text, returning ok(value) or error(reason).", "alx> NaiveDateTime.from_iso8601(\"2026-01-05T13:04:05\")", "ok(~N[2026-01-05 13:04:05])")
	doc("NaiveDateTime.from_iso8601!", "Parses date and time text; fails when it is invalid.", "alx> NaiveDateTime.from_iso8601!(\"2026-01-05 13:04:05\")", "~N[2026-01-05 13:04:05]")
	doc("NaiveDateTime.new", "Builds from a date and a time, or from year, month, day, hour, minute and second.", "alx> NaiveDateTime.new(~D[2026-01-05], ~T[13:04:05])", "ok(~N[2026-01-05 13:04:05])", "alx> NaiveDateTime.new(2026, 1, 5, 13, 4, 5)", "ok(~N[2026-01-05 13:04:05])")
	doc("NaiveDateTime.new!", "Builds from a date and a time, or from six numbers; fails when invalid.", "alx> NaiveDateTime.new!(~D[2026-01-05], ~T[13:04:05])", "~N[2026-01-05 13:04:05]")
	doc("NaiveDateTime.to_date", "The date part.", "alx> NaiveDateTime.to_date(~N[2026-01-05 13:04:05])", "~D[2026-01-05]")
	doc("NaiveDateTime.to_iso8601", "The value as YYYY-MM-DDTHH:MM:SS text.", "alx> NaiveDateTime.to_iso8601(~N[2026-01-05 13:04:05])", "\"2026-01-05T13:04:05\"")
	doc("NaiveDateTime.to_string", "The value as YYYY-MM-DD HH:MM:SS text.", "alx> NaiveDateTime.to_string(~N[2026-01-05 13:04:05])", "\"2026-01-05 13:04:05\"")
	doc("NaiveDateTime.to_time", "The time part.", "alx> NaiveDateTime.to_time(~N[2026-01-05 13:04:05])", "~T[13:04:05]")
	doc("NaiveDateTime.utc_now", "The current date and time in UTC, without a zone.", "alx> NaiveDateTime.after?(NaiveDateTime.utc_now(), ~N[2020-01-01 00:00:00])", "true")

	doc("DateTime.add", "Adds a number of seconds.", "alx> DateTime.add(~U[2026-01-05T23:59:59Z], 2)", "~U[2026-01-06T00:00:01Z]")
	doc("DateTime.after?", "Reports whether the first is later than the second.", "alx> DateTime.after?(~U[2026-01-06T00:00:00Z], ~U[2026-01-05T00:00:00Z])", "true")
	doc("DateTime.before?", "Reports whether the first is earlier than the second.", "alx> DateTime.before?(~U[2026-01-06T00:00:00Z], ~U[2026-01-05T00:00:00Z])", "false")
	doc("DateTime.compare", "Returns :lt, :eq or :gt as the first is earlier than, equal to or later than the second.", "alx> DateTime.compare(~U[2026-01-06T00:00:00Z], ~U[2026-01-05T00:00:00Z])", ":gt")
	doc("DateTime.diff", "The number of seconds from the second to the first.", "alx> DateTime.diff(~U[2026-01-05T00:01:00Z], ~U[2026-01-05T00:00:00Z])", "60")
	doc("DateTime.from_iso8601", "Parses text with a zone offset, returning the moment in UTC with the offset in seconds.", "alx> DateTime.from_iso8601(\"2026-01-05T13:04:05+02:00\")", "ok({~U[2026-01-05T11:04:05Z], 7200})")
	doc("DateTime.from_naive!", "Interprets a naive date and time as UTC.", "alx> DateTime.from_naive!(~N[2026-01-05 13:04:05])", "~U[2026-01-05T13:04:05Z]")
	doc("DateTime.from_unix", "The moment a number of seconds after the Unix epoch.", "alx> DateTime.from_unix(86400)", "ok(~U[1970-01-02T00:00:00Z])")
	doc("DateTime.from_unix!", "The moment a number of seconds after the Unix epoch; fails when out of range.", "alx> DateTime.from_unix!(0)", "~U[1970-01-01T00:00:00Z]")
	doc("DateTime.to_date", "The date part.", "alx> DateTime.to_date(~U[2026-01-05T13:04:05Z])", "~D[2026-01-05]")
	doc("DateTime.to_iso8601", "The value as ISO 8601 text, ending in Z in UTC and in the offset, such as +01:00, in another zone.", "alx> DateTime.to_iso8601(~U[2026-01-05T13:04:05Z])", "\"2026-01-05T13:04:05Z\"")
	doc("DateTime.to_naive", "The same date and time without the zone.", "alx> DateTime.to_naive(~U[2026-01-05T13:04:05Z])", "~N[2026-01-05 13:04:05]")
	doc("DateTime.to_string", "The value as text, ending in Z in UTC; in another zone, with the offset, the zone's abbreviation and its name.", "alx> DateTime.to_string(~U[2026-01-05T13:04:05Z])", "\"2026-01-05 13:04:05Z\"")
	doc("DateTime.to_time", "The time part.", "alx> DateTime.to_time(~U[2026-01-05T13:04:05Z])", "~T[13:04:05]")
	doc("DateTime.to_unix", "Seconds since the Unix epoch.", "alx> DateTime.to_unix(~U[1970-01-02T00:00:00Z])", "86400")
	doc("DateTime.utc_now", "The current moment.", "alx> DateTime.after?(DateTime.utc_now(), ~U[2020-01-01T00:00:00Z])", "true")

	doc("File.append", "Appends text to a file, creating it when missing.", "alx> File.write(\"doc_append.txt\", \"a\")", "ok({})", "alx> File.append(\"doc_append.txt\", \"b\")", "ok({})", "alx> File.read(\"doc_append.txt\")", "ok(\"ab\")")
	doc("File.cp", "Copies a file.", "alx> File.write!(\"doc_cp.txt\", \"data\")", "alx> File.cp(\"doc_cp.txt\", \"doc_cp_copy.txt\")", "ok({})", "alx> File.read!(\"doc_cp_copy.txt\")", "\"data\"")
	doc("File.cwd", "The working directory, as a result.", "alx> File.cwd() == ok(File.cwd!())", "true")
	doc("File.cwd!", "The working directory; fails when it cannot be determined.", "alx> String.length(File.cwd!()) > 0", "true")
	doc("File.dir?", "Reports whether the path is a directory.", "alx> File.dir?(\".\")", "true")
	doc("File.exists", "Reports whether the path exists. Same as File.exists?.", "alx> File.exists(\"no_such_file.txt\")", "false")
	doc("File.exists?", "Reports whether the path exists.", "alx> File.exists?(\".\")", "true")
	doc("File.list", "The names in a directory, sorted. Same as File.ls.", "alx> File.mkdir_p(\"doc_list\")", "ok({})", "alx> File.write!(\"doc_list/a.txt\", \"\")", "alx> File.list(\"doc_list\")", "ok([\"a.txt\"])")
	doc("File.ls", "The names in a directory, sorted.", "alx> File.mkdir_p(\"doc_ls\")", "ok({})", "alx> File.write!(\"doc_ls/a.txt\", \"\")", "alx> File.ls(\"doc_ls\")", "ok([\"a.txt\"])")
	doc("File.ls!", "The names in a directory, sorted; fails when it cannot be read.", "alx> File.mkdir_p(\"doc_ls_bang\")", "ok({})", "alx> File.ls!(\"doc_ls_bang\")", "Enum.take([\"\"], 0)")
	doc("File.mkdir", "Creates a directory whose parent exists.", "alx> File.mkdir(\"doc_mkdir\")", "ok({})", "alx> File.dir?(\"doc_mkdir\")", "true")
	doc("File.mkdir_p", "Creates a directory and any missing parents; succeeds when it already exists.", "alx> File.mkdir_p(\"doc_mkdir_p/a/b\")", "ok({})")
	doc("File.read", "Reads a whole file, returning ok(contents) or error(reason).", "alx> File.write!(\"doc_read.txt\", \"hello\")", "alx> File.read(\"doc_read.txt\")", "ok(\"hello\")",
		"alx> case File.read(\"no_such_file.txt\") do", "...>   ok(text) -> text", "...>   error(_) -> \"missing\"", "...> end", "\"missing\"")
	doc("File.read!", "Reads a whole file; fails when it cannot be read.", "alx> File.write!(\"doc_read_bang.txt\", \"hello\")", "alx> File.read!(\"doc_read_bang.txt\")", "\"hello\"")
	doc("File.regular?", "Reports whether the path is an ordinary file.", "alx> File.regular?(\".\")", "false")
	doc("File.remove", "Deletes a file. Same as File.rm.", "alx> File.write!(\"doc_remove.txt\", \"\")", "alx> File.remove(\"doc_remove.txt\")", "ok({})")
	doc("File.rename", "Renames or moves a file or directory.", "alx> File.write!(\"doc_rename.txt\", \"x\")", "alx> File.rename(\"doc_rename.txt\", \"doc_renamed.txt\")", "ok({})", "alx> File.exists?(\"doc_rename.txt\")", "false")
	doc("File.rm", "Deletes a file.", "alx> File.write!(\"doc_rm.txt\", \"\")", "alx> File.rm(\"doc_rm.txt\")", "ok({})", "alx> File.exists?(\"doc_rm.txt\")", "false")
	doc("File.rm!", "Deletes a file; fails when it cannot be deleted.", "alx> File.write!(\"doc_rm_bang.txt\", \"\")", "alx> File.rm!(\"doc_rm_bang.txt\")")
	doc("File.rm_rf", "Deletes a file or a directory with everything in it; succeeds when the path does not exist.", "alx> File.mkdir_p(\"doc_rm_rf/a\")", "ok({})", "alx> File.rm_rf(\"doc_rm_rf\")", "ok({})")
	doc("File.rmdir", "Deletes an empty directory.", "alx> File.mkdir(\"doc_rmdir\")", "ok({})", "alx> File.rmdir(\"doc_rmdir\")", "ok({})")
	doc("File.stream!", "A lazy stream of a file's lines, each keeping its line ending; with a size, of chunks of that many bytes. The file is read as the stream is consumed and closed when it ends.",
		"alx> File.write!(\"doc_stream.txt\", \"one\\ntwo\\nthree\\n\")", "alx> File.stream!(\"doc_stream.txt\") |> Stream.map(&String.trim(&1)) |> Enum.take(2)", "[\"one\", \"two\"]",
		"alx> File.stream!(\"doc_stream.txt\", 4) |> Enum.take(1)", "[\"one\\n\"]")
	doc("File.touch", "Creates an empty file, or updates the modification time of an existing one.", "alx> File.touch(\"doc_touch.txt\")", "ok({})", "alx> File.exists?(\"doc_touch.txt\")", "true")
	doc("File.write", "Writes text to a file, replacing its contents.", "alx> File.write(\"doc_write.txt\", \"hello\")", "ok({})")
	doc("File.write!", "Writes text to a file; fails when it cannot be written.", "alx> File.write!(\"doc_write_bang.txt\", \"hello\")", "alx> File.read!(\"doc_write_bang.txt\")", "\"hello\"")

	doc("Path.absname", "The path made absolute against the working directory.", "alx> Path.absname(\"a.txt\") == Path.join(File.cwd!(), \"a.txt\")", "true")
	doc("Path.basename", "The last component, optionally without an extension.", "alx> Path.basename(\"src/main.alc\")", "\"main.alc\"", "alx> Path.basename(\"src/main.alc\", \".alc\")", "\"main\"")
	doc("Path.dirname", "Everything before the last component.", "alx> Path.dirname(\"src/app/main.alc\")", "\"src/app\"")
	doc("Path.expand", "An absolute path with . and .. resolved and a leading ~ replaced by the home directory.", "alx> String.ends_with?(Path.expand(\"a/b/../c\"), \"/a/c\")", "true")
	doc("Path.extname", "The extension of the last component, with its dot.", "alx> Path.extname(\"main.alc\")", "\".alc\"", "alx> Path.extname(\"README\")", "\"\"")
	doc("Path.join", "Joins path components with a separator.", "alx> Path.join(\"src\", \"main.alc\")", "\"src/main.alc\"", "alx> Path.join([\"a\", \"b\", \"c\"])", "\"a/b/c\"")
	doc("Path.relative_to", "The path relative to a base, or unchanged when it is not under the base.", "alx> Path.relative_to(\"/usr/local/bin\", \"/usr\")", "\"local/bin\"")
	doc("Path.rootname", "The path without its extension, or without the given one.", "alx> Path.rootname(\"src/main.alc\")", "\"src/main\"", "alx> Path.rootname(\"main.alc\", \".go\")", "\"main.alc\"")
	doc("Path.split", "The components of a path.", "alx> Path.split(\"src/app/main.alc\")", "[\"src\", \"app\", \"main.alc\"]")
	doc("Path.wildcard", "The existing paths matching a glob pattern, sorted.", "alx> File.mkdir_p(\"doc_wildcard\")", "ok({})", "alx> File.write!(\"doc_wildcard/a.txt\", \"\")", "alx> Path.wildcard(\"doc_wildcard/*.txt\")", "[\"doc_wildcard/a.txt\"]")

	legacy("IO.puts", "IO.puts(string)")
	doc("IO.puts", "Writes a string to standard output, or to the device given first, :stdio or :stderr, followed by a newline. Interpolate other values: IO.puts(\"total: #{n}\").", "alx> IO.puts(\"hello\")", "alx> IO.puts(\"total: #{1 + 2}\")", "alx> IO.puts(:stderr, \"to standard error\")")
	doc("IO.gets", "Writes a prompt and reads one line from standard input without its line ending; none at end of input.")
	doc("IO.inspect", "Writes any value to standard output in source form and returns it, so it can sit in a pipeline.", "alx> [1, 2] |> IO.inspect() |> length()", "2")
	doc("IO.read_all", "Reads all of standard input.")
	doc("IO.read_line", "Reads one line from standard input without its line ending; none at end of input.")
	doc("IO.stream", "A lazy stream of the lines of standard input, each keeping its line ending.")
	doc("IO.warn", "Writes a line to standard error.", "alx> IO.warn(\"careful\")")
	doc("IO.write", "Writes a string to standard output without a newline.", "alx> IO.write(\"no newline\")")

	doc("System.argv", "The command-line arguments after the program name.", "alx> length(System.argv()) >= 0", "true")
	doc("System.cmd", "Runs a program with arguments and returns its combined output with its exit status.", "alx> System.cmd(\"echo\", [\"hello\"])", "{\"hello\\n\", 0}")
	doc("System.cwd!", "The working directory.", "alx> System.cwd!() == File.cwd!()", "true")
	doc("System.env", "The value of an environment variable. Same as System.get_env.", "alx> System.env(\"ALCHEM_NO_SUCH_VARIABLE\")", "none")
	doc("System.find_executable", "The full path of a program on PATH.", "alx> System.find_executable(\"alchem-no-such-program\")", "none")
	doc("System.get_env", "The value of an environment variable as an option, or the default when it is unset.", "alx> System.put_env(\"ALCHEM_DOC_GET\", \"1\")", "alx> System.get_env(\"ALCHEM_DOC_GET\")", "some(\"1\")", "alx> System.get_env(\"ALCHEM_NO_SUCH_VARIABLE\", \"fallback\")", "\"fallback\"")
	doc("System.halt", "Ends the program immediately with an exit status.")
	doc("System.pid", "The operating system's process identifier, as text.", "alx> String.length(System.pid()) > 0", "true")
	doc("System.put_env", "Sets an environment variable for this program and the commands it runs.", "alx> System.put_env(\"ALCHEM_DOC_PUT\", \"on\")", "alx> System.get_env(\"ALCHEM_DOC_PUT\", \"\")", "\"on\"")
	doc("System.tmp_dir", "A directory for temporary files.", "alx> System.tmp_dir() != none", "true")
	doc("System.tmp_dir!", "A directory for temporary files; fails when there is none.", "alx> System.tmp_dir!() != \"\"", "true")
	doc("System.user_home", "The user's home directory.", "alx> System.user_home() != none", "true")
}
